<?php require_once __DIR__ . '/workflow_nav.php'; ?><?php require_once __DIR__ . '/workflow_nav.php'; ?></main></div><script>(function(){var sb=document.querySelector('.sidebar');var h=document.getElementById('sidebarHandle');if(!sb||!h)return;var w=localStorage.getItem('erp_sidebar_w');if(w){sb.style.width=w+'px';}var d=false;h.addEventListener('mousedown',function(e){d=true;e.preventDefault();});document.addEventListener('mousemove',function(e){if(!d)return;var nw=Math.max(130,Math.min(420,e.clientX));sb.style.width=nw+'px';});document.addEventListener('mouseup',function(){if(d){localStorage.setItem('erp_sidebar_w',parseInt(sb.style.width,10));d=false;}});})();</script><script>(function(){var b=document.body;var t=document.createElement("button");t.className="nav-toggle";t.setAttribute("aria-label","Menu");t.innerHTML="&#9776;";function ins(){var h=document.querySelector(".top-header");if(!h){setTimeout(ins,50);return;}h.insertBefore(t,h.firstChild);}ins();t.addEventListener("click",function(e){e.stopPropagation();b.classList.toggle("nav-open");});document.addEventListener("click",function(e){if(!b.classList.contains("nav-open"))return;var s=document.querySelector(".sidebar");if(s&&!s.contains(e.target)&&e.target!==t&&!t.contains(e.target)){b.classList.remove("nav-open");}});})();</script></body></html>
